// Handwritten HTTP adapters. IDL routes are generated by hz.
package maintenance

import (
	"context"
	"github.com/cloudwego/hertz/pkg/app"
	"github.com/yi-nology/rainbow_bridge/biz/maintenanceweb"
)

var api *maintenanceweb.HTTP

func SetAPI(h *maintenanceweb.HTTP) { api = h }
func serve(action string, ctx context.Context, c *app.RequestContext) {
	if api == nil {
		c.JSON(503, map[string]any{"code": 503, "error_type": "MAINTENANCE_NOT_READY", "msg": "此入口需要独立控制服务"})
		return
	}
	api.Serve(action)(ctx, c)
}
func Capabilities(ctx context.Context, c *app.RequestContext)  { serve("capabilities", ctx, c) }
func CreatePlan(ctx context.Context, c *app.RequestContext)    { serve("plan", ctx, c) }
func GetPlan(ctx context.Context, c *app.RequestContext)       { serve("preview", ctx, c) }
func CreateBackup(ctx context.Context, c *app.RequestContext)  { serve("backup", ctx, c) }
func ListBackups(ctx context.Context, c *app.RequestContext)   { serve("backups", ctx, c) }
func VerifyBackup(ctx context.Context, c *app.RequestContext)  { serve("verify", ctx, c) }
func Restore(ctx context.Context, c *app.RequestContext)       { serve("restore", ctx, c) }
func ListTasks(ctx context.Context, c *app.RequestContext)     { serve("tasks", ctx, c) }
func TaskByRequest(ctx context.Context, c *app.RequestContext) { serve("by_request", ctx, c) }
func GetTask(ctx context.Context, c *app.RequestContext)       { serve("task", ctx, c) }
func Resume(ctx context.Context, c *app.RequestContext)        { serve("resume", ctx, c) }
func Abort(ctx context.Context, c *app.RequestContext)         { serve("abort", ctx, c) }
func Cancel(ctx context.Context, c *app.RequestContext)        { serve("cancel", ctx, c) }
